let busy=!1;async function updateValues(){if(!busy){busy=!0;try{let e=await fetch("https://192.168.1.20/status",{cache:"no-store"}),t=await e.json();1==t.gpio?document.getElementById("gpio").innerHTML="<div>La vanne 1 est ouverte</div><div class='vert'></div>":document.getElementById("gpio").innerHTML="<div>La vanne 1 est fermée</div><div class='rouge'></div>",document.getElementById("voltage").innerText=t.voltage+" V"}catch(e){console.log("Erreur updateValues:",e.message)}finally{busy=!1}}}updateValues(),setInterval((()=>{updateValues()}),5e3);const btn=document.querySelector(".btn");btn.addEventListener("click",(async()=>{try{await fetch("https://192.168.1.20/togglevanne2",{cache:"no-store"}),updateValues()}catch(e){console.log("Erreur button:",e.message)}}));const input=document.querySelector("#input");input.addEventListener("change",(async e=>{try{await fetch("https://192.168.1.20/pwm?v="+e.target.value,{cache:"no-store"})}catch(e){console.log("Erreur PWM:",e.message)}}));